<?php
/** Integrated Forms workspace: visual definition editor, recoverable catalog, private receipts and bounded history; all editorial output escaped. */
declare(strict_types=1);
use DBLESSCMS\{FormsModel,FormsDelivery,Security,Icons,HttpError};
use function DBLESSCMS\e;
/** Translate plugin hardcoded controls; receive key, return plain text for contextual escaping without I/O. */
$t=static fn(string $key):string=>$context->language->text('forms.'.$key);
/** Construct a fixed private route URL; receive route/optional ID, return local address without dispatch or writes. */
$url=static fn(string $route,string $id=''):string=>$context->base.'/cms-admin/?'.http_build_query(['view'=>'plugin-panel','plugin'=>'forms','route'=>$route]+($id!==''?['id'=>$id]:[]));
$repo=FormsModel::repository($context->store);$snapshot=$repo->read();$csrf=Security::token();$route=$context->route;$id=$_GET['id']??'';if(!is_string($id)||$id!==''&&!FormsModel::id($id))throw new HttpError(404,'Form unavailable.','forms.error.missing');
$record=$snapshot['data']['forms'][$id]??FormsModel::empty();if($route==='editor'&&(!isset($snapshot['data']['forms'][$id])||$record['deleted']))throw new HttpError(404,'Form unavailable.','forms.error.missing');
?>
<div class="forms-plugin"><p class="notice error" role="alert" tabindex="-1" data-forms-admin-status hidden></p>
<?php if(in_array($route,['overview','trash'],true)): $rows=array_filter($snapshot['data']['forms'],static fn(array $form):bool=>$form['deleted']===($route==='trash')); ?>
<?php if($route==='overview'): ?><p><a class="button-primary" href="<?= e($url('new')) ?>"><?= e($t('new')) ?></a></p><?php endif; ?>
<section class="panel extension-panel"><div class="table-scroll"><table class="extension-table"><thead><tr><?php foreach(['name','description','status','actions'] as $key): ?><th scope="col"><?= e($t($key)) ?></th><?php endforeach; ?></tr></thead><tbody>
<?php foreach($rows as $form): ?><tr><td data-label="<?= e($t('name')) ?>"><strong><?= e($form['name']) ?></strong><div class="form-snippet"><code>{{forms:form id="<?= e($form['id']) ?>"}}</code></div></td><td data-label="<?= e($t('description')) ?>"><?= e($form['description']) ?></td><td data-label="<?= e($t('status')) ?>"><?= e($t($form['demo']?'demo':$form['status'])) ?></td><td data-label="<?= e($t('actions')) ?>"><div class="row-actions"><?php if(!$form['deleted']): ?><a class="icon-button" href="<?= e($url('editor',$form['id'])) ?>" title="<?= e($t('edit')) ?>" aria-label="<?= e($t('edit')) ?>"><?= Icons::svg('edit',$context->base) ?></a><?php if($form['status']==='published'): ?><a class="icon-button" href="<?= e($context->base.'/plugins/forms/form?id='.$form['id']) ?>" title="<?= e($t('preview')) ?>" aria-label="<?= e($t('preview')) ?>"><?= Icons::svg('eye',$context->base) ?></a><?php endif; ?><?php endif; ?><form method="post" action="<?= e($context->url($form['deleted']?'recover':'delete')) ?>" data-forms-admin><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><input type="hidden" name="revision" value="<?= e($snapshot['revision']) ?>"><input type="hidden" name="id" value="<?= e($form['id']) ?>"><button type="submit" class="icon-button" title="<?= e($t($form['deleted']?'recover':'delete')) ?>" aria-label="<?= e($t($form['deleted']?'recover':'delete')) ?>"><?= Icons::svg($form['deleted']?'history':'uninstall',$context->base) ?></button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php if($rows===[]): ?><p class="empty-state"><?= e($t('empty')) ?></p><?php endif; ?></section>
<?php elseif(in_array($route,['new','editor'],true)): ?>
<p class="notice"><?= e($t('help')) ?></p><form method="post" action="<?= e($context->url('save')) ?>" data-forms-admin data-forms-editor>
<input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><input type="hidden" name="revision" value="<?= e($snapshot['revision']) ?>"><input type="hidden" name="original" value="<?= e($id) ?>"><input type="hidden" name="editor" value="1">
<section class="panel"><h2><?= e($t('identity')) ?></h2><div class="field-grid">
<?php foreach(['id','name','description'] as $key): ?><label><?= e($t($key)) ?><input name="<?= e($key) ?>" value="<?= e($record[$key]) ?>" maxlength="<?= $key==='description'?1000:($key==='id'?48:200) ?>" <?= $key==='id'&&$id!==''?'readonly':'' ?> required></label><?php endforeach; ?>
<label><?= e($t('status')) ?><select name="status"><?php foreach(['draft','published'] as $status): ?><option value="<?= e($status) ?>" <?= $record['status']===$status?'selected':'' ?>><?= e($t($status)) ?></option><?php endforeach; ?></select></label><label class="check-option"><input type="checkbox" name="demo" value="1" <?= $record['demo']?'checked':'' ?>><?= e($t('demo')) ?></label></div></section>
<section class="panel"><h2><?= e($t('privacy')) ?></h2><div class="field-grid">
<?php foreach(['purpose','noticeVersion','noticeText','consentText'] as $key): ?><label class="<?= in_array($key,['purpose','noticeText','consentText'],true)?'wide':'' ?>"><?= e($t($key)) ?><input name="<?= e($key) ?>" maxlength="<?= $key==='noticeText'?3000:1000 ?>" value="<?= e($record[$key]) ?>" <?= $key==='consentText'?'':'required' ?>></label><?php endforeach; ?>
<label><?= e($t('legalBasis')) ?><select name="legalBasis"><option value=""></option><?php foreach(['precontract','consent','legitimate-interest','legal-obligation','other'] as $basis): ?><option value="<?= e($basis) ?>" <?= $record['legalBasis']===$basis?'selected':'' ?>><?= e($t('basis.'.str_replace('-','_',$basis))) ?></option><?php endforeach; ?></select></label>
<label><?= e($t('privacyPage')) ?><select name="privacyPage"><option value=""></option><?php foreach($context->store->pages() as $slug=>$page)if($page['data']['status']==='published'): ?><option value="<?= e($slug) ?>" <?= $record['privacyPage']===$slug?'selected':'' ?>><?= e($page['data']['meta']['title']) ?></option><?php endif; ?></select></label>
<label><?= e($t('destination')) ?><select name="destination"><?php foreach(['contact','privacy'] as $destination): ?><option value="<?= e($destination) ?>" <?= $record['destination']===$destination?'selected':'' ?>><?= e($t('destination.'.$destination)) ?></option><?php endforeach; ?></select></label>
<label><?= e($t('retainDays')) ?><input type="number" min="0" max="365" name="retainDays" value="<?= $record['retainDays'] ?>" required></label>
<?php foreach(['submitLabel','successText'] as $key): ?><label><?= e($t($key)) ?><input name="<?= e($key) ?>" maxlength="500" value="<?= e($record[$key]) ?>" required></label><?php endforeach; ?>
</div></section>
<section class="panel"><h2><?= e($t('fields')) ?></h2><div data-form-field-list>
<?php foreach($record['fields'] as $index=>$field): ?><fieldset class="form-field-row"><legend><?= e($t('field')) ?> <?= $index+1 ?></legend><div class="field-grid">
<label><?= e($t('fieldName')) ?><input name="fields[<?= $index ?>][name]" maxlength="48" value="<?= e($field['name']) ?>" required></label><label><?= e($t('fieldLabel')) ?><input name="fields[<?= $index ?>][label]" maxlength="200" value="<?= e($field['label']) ?>" required></label>
<label><?= e($t('fieldType')) ?><select name="fields[<?= $index ?>][type]"><?php foreach(['text','email','tel','textarea','select','radio','checkbox'] as $type): ?><option value="<?= e($type) ?>" <?= $field['type']===$type?'selected':'' ?>><?= e($t('type.'.$type)) ?></option><?php endforeach; ?></select></label>
<label><?= e($t('maxLength')) ?><input type="number" name="fields[<?= $index ?>][maxLength]" min="1" max="10000" value="<?= $field['maxLength'] ?>" required></label><label><?= e($t('options')) ?><input name="fields[<?= $index ?>][options]" value="<?= e(implode(' | ',$field['options'])) ?>" maxlength="6000"></label><label><?= e($t('autocomplete')) ?><select name="fields[<?= $index ?>][autocomplete]"><?php foreach(['off','name','given-name','family-name','email','tel','organization','country-name'] as $auto): ?><option value="<?= e($auto) ?>" <?= $field['autocomplete']===$auto?'selected':'' ?>><?= e($auto) ?></option><?php endforeach; ?></select></label><label class="check-option"><input type="checkbox" name="fields[<?= $index ?>][required]" value="1" <?= $field['required']?'checked':'' ?>><?= e($t('required')) ?></label></div><button type="button" class="button-quiet" data-form-field-remove><?= e($t('removeField')) ?></button></fieldset><?php endforeach; ?>
</div><button type="button" class="button-secondary" data-form-field-add><?= e($t('addField')) ?></button></section>
<div class="savebar"><a href="<?= e($url('overview')) ?>"><?= e($t('overview')) ?></a><button type="submit" class="button-primary"><?= e($t('save')) ?></button></div></form>
<?php elseif($route==='history'): ?><section class="panel"><?php foreach($repo->history() as $backup): ?><form class="history-row" method="post" action="<?= e($context->url('restore')) ?>" data-forms-admin><span><?= e(substr($backup,0,22)) ?></span><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><input type="hidden" name="revision" value="<?= e($snapshot['revision']) ?>"><input type="hidden" name="backup" value="<?= e($backup) ?>"><button type="submit" class="button-secondary"><?= e($t('recover')) ?></button></form><?php endforeach; ?></section>
<?php elseif($route==='submissions'): ?><p class="notice"><?= e($t('receiptHelp')) ?></p><section class="panel extension-panel"><div class="table-scroll"><table class="extension-table"><thead><tr><?php foreach(['id','name','status','actions'] as $key): ?><th scope="col"><?= e($t($key)) ?></th><?php endforeach; ?></tr></thead><tbody>
<?php foreach(array_slice(glob(FormsDelivery::directory($context->store).'/*.json')?:[],0,2000) as $file): $receipt=FormsDelivery::receipt($file);if($receipt['expiresAt']<=time())continue;if($receipt['retainUntil']<=time())$receipt['values']=[]; ?><tr><td><code><?= e($receipt['id']) ?></code><br><?= e(gmdate('Y-m-d H:i',$receipt['createdAt'])) ?> UTC</td><td><?= e($receipt['form']) ?><?php if($receipt['values']!==[]): ?><details><summary><?= e($t('retained')) ?></summary><dl><?php foreach($receipt['values'] as $name=>$value): ?><dt><?= e($name) ?></dt><dd><?= e($value) ?></dd><?php endforeach; ?></dl></details><?php endif; ?></td><td><?= e($t('delivery.'.$receipt['status'])) ?></td><td><?php if($receipt['values']!==[]): ?><form method="post" action="<?= e($context->url('erase')) ?>" data-forms-admin data-confirm="<?= e($t('confirmErase')) ?>"><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><input type="hidden" name="revision" value="<?= e(hash_file('sha256',$file)) ?>"><input type="hidden" name="id" value="<?= e($receipt['id']) ?>"><button type="submit" class="button-secondary"><?= e($t('erase')) ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
</div>
